import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import {
  Accordion,
  AccordionItem,
  Button,
  Flex,
  FormField,
  Heading,
  Image,
  Input,
  Select,
  Text,
  Textarea,
} from "@paraxe/react";
import {
  defaultStudioLabels,
  prepareStudioBrief,
  sampleProjects,
  sampleServices,
  validateStudio,
  type Studio01Brief,
  type Studio01Props,
} from "../shared/studio";
import "../shared/studio.css";
export function Studio01({
  name = "Paraxe studio",
  location = "Independent / working everywhere",
  eyebrow = "IDENTITY, DIGITAL & CREATIVE DIRECTION",
  title = "A good idea,\nmade unmistakable.",
  description = "We help ambitious people find the clearest expression of what they do. Thoughtful identities and digital experiences, made with care.",
  availability = "A small studio for considered collaborations.",
  projects = sampleProjects,
  services = sampleServices,
  inquiryTitle = "Let's make something worth caring about.",
  inquiryDescription = "A first conversation is a good place to start. Tell us what you have in mind.",
  privacyHref,
  notice = "Sample studio and concept projects. Replace the work, copy, and enquiry integration with your own.",
  labels: providedLabels,
  submitBrief,
}: Studio01Props) {
  const id = `studio-${useId()}`;
  const labels = { ...defaultStudioLabels, ...providedLabels };
  validateStudio(projects, services);
  const empty: Studio01Brief = {
    name: "",
    email: "",
    serviceId: "",
    message: "",
  };
  const [draft, setDraft] = useState(empty);
  const [errors, setErrors] = useState<
    Partial<Record<keyof Studio01Brief, string>>
  >({});
  const [pending, setPending] = useState(false);
  const [status, setStatus] = useState<"" | "success" | "error">("");
  const busy = useRef(false);
  useEffect(() => {
    if (
      draft.serviceId &&
      !services.some((service) => service.id === draft.serviceId)
    )
      setDraft((current) => ({ ...current, serviceId: "" }));
  }, [services, draft.serviceId]);
  const change = (key: keyof Studio01Brief, value: string) => {
    setDraft((current) => ({ ...current, [key]: value }));
    setStatus("");
  };
  const describedBy = (key: keyof Studio01Brief) =>
    errors[key] ? `${id}-${key}-error` : undefined;
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (busy.current || !submitBrief || !services.length) return;
    const prepared = prepareStudioBrief(draft, services, labels);
    setErrors(prepared.errors);
    setStatus("");
    if (!prepared.brief) return;
    busy.current = true;
    setPending(true);
    try {
      await submitBrief(prepared.brief);
      setDraft(empty);
      setStatus("success");
    } catch {
      setStatus("error");
    } finally {
      busy.current = false;
      setPending(false);
    }
  }
  return (
    <main className="studio01" aria-labelledby={`${id}-title`}>
      <div className="studio01-inner">
        <Flex
          className="studio01-masthead"
          justify="between"
          align="center"
          wrap
        >
          <a className="studio01-brand" href={`#${id}-top`}>
            {name}
            <span aria-hidden="true">.</span>
          </a>
          <nav aria-label="Studio navigation">
            <Flex wrap>
              <a href={`#${id}-work`}>Selected work</a>
              <a href={`#${id}-approach`}>Our approach</a>
              <a href={`#${id}-inquiry`}>Start a conversation</a>
            </Flex>
          </nav>
        </Flex>
        <header className="studio01-hero" id={`${id}-top`}>
          <p className="studio01-kicker">{eyebrow}</p>
          <Heading level="h1" id={`${id}-title`}>
            {title}
          </Heading>
          <Flex className="studio01-introduction" justify="between" align="end">
            <Text>{description}</Text>
            <div>
              <span className="studio01-availability">{availability}</span>
              <a className="btn btn-primary" href={`#${id}-inquiry`}>
                Tell us about your project{" "}
                <span aria-hidden="true">{"\u2197"}</span>
              </a>
            </div>
          </Flex>
        </header>
        <section
          className="studio01-work"
          id={`${id}-work`}
          aria-labelledby={`${id}-work-title`}
        >
          <Flex
            className="studio01-section-heading"
            justify="between"
            align="end"
            wrap
          >
            <div>
              <p className="studio01-kicker">
                A FEW CONSIDERED STARTING POINTS
              </p>
              <Heading level="h2" id={`${id}-work-title`}>
                Selected work.
              </Heading>
            </div>
            <span>{String(projects.length).padStart(2, "0")} studies</span>
          </Flex>
          <Flex className="studio01-projects" wrap>
            {projects.map((project, index) => (
              <article className="studio01-project" key={project.id}>
                <div className="studio01-project-media">
                  {project.imageSrc ? (
                    <Image
                      src={project.imageSrc}
                      alt={project.imageAlt ?? project.title}
                      aspectRatio="video"
                      loading="lazy"
                    />
                  ) : (
                    <div className="studio01-project-art" aria-hidden="true">
                      <span>{project.category}</span>
                      <strong>{project.mark}</strong>
                      <span>
                        {String(index + 1).padStart(2, "0")} / {project.year}
                      </span>
                    </div>
                  )}
                </div>
                <Flex
                  className="studio01-project-meta"
                  justify="between"
                  align="baseline"
                  wrap
                >
                  <Heading level="h3">
                    {project.href ? (
                      <a href={project.href}>{project.title}</a>
                    ) : (
                      project.title
                    )}
                  </Heading>
                  <span>{project.year}</span>
                </Flex>
                <Text tone="muted">{project.description}</Text>
              </article>
            ))}
          </Flex>
          {!projects.length && (
            <Text tone="muted">New work will appear here.</Text>
          )}
        </section>
        <section
          className="studio01-approach"
          id={`${id}-approach`}
          aria-labelledby={`${id}-approach-title`}
        >
          <Flex align="start">
            <div className="studio01-approach-intro">
              <p className="studio01-kicker">CLARITY BEFORE COMPLEXITY</p>
              <Heading level="h2" id={`${id}-approach-title`}>
                Good work starts with a good question.
              </Heading>
              <Text tone="muted">
                A focused set of capabilities, shaped around what the work
                needs.
              </Text>
            </div>
            <div className="studio01-services">
              {services.length ? (
                <Accordion defaultOpen={[services[0].id]}>
                  {services.map((service, index) => (
                    <AccordionItem
                      key={service.id}
                      id={service.id}
                      headingLevel="h3"
                      trigger={
                        <Flex as="span" align="baseline" size="small">
                          <span
                            className="studio01-service-index"
                            aria-hidden="true"
                          >
                            {String(index + 1).padStart(2, "0")}
                          </span>
                          <span>{service.title}</span>
                        </Flex>
                      }
                    >
                      <Text tone="muted">{service.description}</Text>
                      <ul>
                        {service.deliverables.map((item, i) => (
                          <li key={i}>{item}</li>
                        ))}
                      </ul>
                    </AccordionItem>
                  ))}
                </Accordion>
              ) : (
                <Text tone="muted">
                  Our next ways of working will appear here.
                </Text>
              )}
            </div>
          </Flex>
        </section>
        <section
          className="studio01-inquiry"
          id={`${id}-inquiry`}
          aria-labelledby={`${id}-inquiry-title`}
        >
          <Flex align="start">
            <div className="studio01-inquiry-intro">
              <p className="studio01-kicker">AN IDEA IS ENOUGH TO BEGIN</p>
              <Heading level="h2" id={`${id}-inquiry-title`}>
                {inquiryTitle}
              </Heading>
              <Text>{inquiryDescription}</Text>
              <p className="studio01-location">{location}</p>
            </div>
            <form
              className="studio01-form"
              aria-label="Project enquiry"
              aria-busy={pending || undefined}
              onSubmit={submit}
            >
              <Flex className="studio01-name-row" wrap>
                <FormField
                  id={`${id}-name`}
                  label={labels.name}
                  error={errors.name}
                  required
                >
                  <Input
                    id={`${id}-name`}
                    name="name"
                    autocomplete="name"
                    required
                    modelValue={draft.name}
                    onModelValueChange={(value) => change("name", value)}
                    disabled={pending}
                    invalid={!!errors.name}
                    describedBy={describedBy("name")}
                  />
                </FormField>
                <FormField
                  id={`${id}-email`}
                  label={labels.email}
                  error={errors.email}
                  required
                >
                  <Input
                    id={`${id}-email`}
                    name="email"
                    type="email"
                    autocomplete="email"
                    required
                    modelValue={draft.email}
                    onModelValueChange={(value) => change("email", value)}
                    disabled={pending}
                    invalid={!!errors.email}
                    describedBy={describedBy("email")}
                  />
                </FormField>
              </Flex>
              <FormField
                id={`${id}-serviceId`}
                label={labels.service}
                error={errors.serviceId}
                required
              >
                <Select
                  id={`${id}-serviceId`}
                  name="serviceId"
                  required
                  modelValue={draft.serviceId}
                  onModelValueChange={(value) => change("serviceId", value)}
                  disabled={pending || !services.length}
                  invalid={!!errors.serviceId}
                  describedBy={describedBy("serviceId")}
                >
                  <option value="">{labels.chooseService}</option>
                  {services.map((service) => (
                    <option key={service.id} value={service.id}>
                      {service.title}
                    </option>
                  ))}
                </Select>
              </FormField>
              <FormField
                id={`${id}-message`}
                label={labels.message}
                error={errors.message}
                required
              >
                <Textarea
                  id={`${id}-message`}
                  name="message"
                  rows={5}
                  required
                  modelValue={draft.message}
                  onModelValueChange={(value) => change("message", value)}
                  disabled={pending}
                  error={!!errors.message}
                  describedBy={describedBy("message")}
                />
              </FormField>
              {status && (
                <p
                  className="studio01-feedback"
                  role={status === "error" ? "alert" : "status"}
                >
                  {status === "error" ? labels.failure : labels.success}
                </p>
              )}
              {(!submitBrief || !services.length) && (
                <Text className="studio01-form-note" tone="muted">
                  {!services.length ? labels.noServices : labels.unavailable}
                </Text>
              )}
              <Flex
                className="studio01-form-actions"
                align="center"
                justify="between"
                wrap
              >
                <Button
                  type="submit"
                  loading={pending}
                  disabled={!submitBrief || !services.length}
                >
                  {pending ? labels.pending : labels.submit}
                </Button>
                {privacyHref && <a href={privacyHref}>Privacy information</a>}
              </Flex>
            </form>
          </Flex>
        </section>
        <footer className="studio01-footer">
          <Flex justify="between" wrap>
            <strong>{name}</strong>
            <a href={`#${id}-top`}>
              Back to top <span aria-hidden="true">{"\u2191"}</span>
            </a>
          </Flex>
          {notice && <Text tone="muted">{notice}</Text>}
        </footer>
      </div>
    </main>
  );
}

export interface Studio01Project {
  id: string;
  title: string;
  category: string;
  year: string;
  description: string;
  mark: string;
  imageSrc?: string;
  imageAlt?: string;
  href?: string;
}
export interface Studio01Service {
  id: string;
  title: string;
  description: string;
  deliverables: readonly string[];
}
export interface Studio01Brief {
  name: string;
  email: string;
  serviceId: string;
  message: string;
}
export interface Studio01Labels {
  name: string;
  email: string;
  service: string;
  chooseService: string;
  message: string;
  submit: string;
  pending: string;
  success: string;
  failure: string;
  unavailable: string;
  noServices: string;
  invalidName: string;
  invalidEmail: string;
  invalidService: string;
  invalidMessage: string;
}
export interface Studio01Props {
  name?: string;
  location?: string;
  eyebrow?: string;
  title?: string;
  description?: string;
  availability?: string;
  projects?: readonly Studio01Project[];
  services?: readonly Studio01Service[];
  inquiryTitle?: string;
  inquiryDescription?: string;
  privacyHref?: string;
  notice?: string;
  labels?: Partial<Studio01Labels>;
  submitBrief?: (brief: Studio01Brief) => void | Promise<void>;
}
export const defaultStudioLabels: Studio01Labels = {
  name: "Your name",
  email: "Email address",
  service: "What can we help with?",
  chooseService: "Choose a starting point",
  message: "Tell us a little about the idea",
  submit: "Send your project brief",
  pending: "Sending your brief...",
  success: "Your brief was submitted.",
  failure: "We couldn't send your brief. Please try again.",
  unavailable:
    "Connect an enquiry handler to receive briefs. No details are sent from this preview.",
  noServices: "New enquiries are currently unavailable.",
  invalidName: "Please enter your name.",
  invalidEmail: "Please enter a valid email address.",
  invalidService: "Please choose one of the current services.",
  invalidMessage: "Please tell us a little about your project.",
};
export const sampleProjects: readonly Studio01Project[] = [
  {
    id: "common",
    title: "Common ground",
    category: "Identity / concept study",
    year: "2026",
    description: "A considered identity for ideas that bring people together.",
    mark: "Common\nground.",
  },
  {
    id: "notes",
    title: "Notes on the everyday",
    category: "Digital / concept study",
    year: "2026",
    description: "An editorial home for the things worth paying attention to.",
    mark: "Notes.",
  },
];
export const sampleServices: readonly Studio01Service[] = [
  {
    id: "direction",
    title: "A clear direction.",
    description:
      "Find the idea at the centre of the work, and give the next decisions something to stand on.",
    deliverables: [
      "Positioning and story",
      "Creative direction",
      "A practical brief",
    ],
  },
  {
    id: "identity",
    title: "An identity with room to grow.",
    description:
      "A useful visual language that feels distinctive and stays coherent as the work changes.",
    deliverables: [
      "Identity and typography",
      "A flexible design system",
      "Guidelines for everyday use",
    ],
  },
  {
    id: "digital",
    title: "A good idea, out in the world.",
    description:
      "Thoughtful websites and digital experiences built around the people who will use them.",
    deliverables: [
      "Website and product design",
      "Component-driven implementation",
      "A considered handover",
    ],
  },
];
export function validateStudio(
  projects: readonly Studio01Project[],
  services: readonly Studio01Service[],
) {
  for (const items of [projects, services]) {
    const ids = new Set<string>();
    for (const item of items) {
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(item.id) || ids.has(item.id))
        throw new RangeError("Studio items require unique anchor-safe IDs.");
      ids.add(item.id);
    }
  }
}
export function prepareStudioBrief(
  draft: Studio01Brief,
  services: readonly Studio01Service[],
  labels: Studio01Labels = defaultStudioLabels,
) {
  const brief = {
    name: draft.name.trim(),
    email: draft.email.trim(),
    serviceId: draft.serviceId,
    message: draft.message.trim(),
  };
  const errors: Partial<Record<keyof Studio01Brief, string>> = {};
  if (!brief.name) errors.name = labels.invalidName;
  if (!/^[^\s@]+@[^\s@]+$/.test(brief.email))
    errors.email = labels.invalidEmail;
  if (!services.some((service) => service.id === brief.serviceId))
    errors.serviceId = labels.invalidService;
  if (!brief.message) errors.message = labels.invalidMessage;
  return { brief: Object.keys(errors).length ? null : brief, errors };
}

.studio01 {
  --studio01-column-gap: var(--space-10);
  --studio01-section-gap: var(--space-12);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
  padding: var(--space-6) var(--container-padding-lg) var(--space-8);
}
.studio01 *,
.studio01 *::before,
.studio01 *::after {
  box-sizing: border-box;
}
.studio01 :is(h1, h2, h3, p, ul) {
  margin: 0;
}
.studio01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.studio01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.studio01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.studio01 :is(header, section) {
  scroll-margin-block-start: var(--space-8);
}
.studio01 .studio01-masthead {
  gap: var(--space-5);
  padding-block-end: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.studio01-brand {
  text-decoration: none;
  font-family: var(--font-family-display);
  font-size: var(--font-size-2xl);
  letter-spacing: var(--letter-spacing-tight);
}
.studio01-brand > span {
  color: var(--brand-primary);
}
.studio01-masthead nav {
  font-size: var(--typography-caption-size);
}
.studio01-masthead nav a {
  text-decoration: none;
}
.studio01-masthead nav a:hover {
  text-decoration: underline;
}
.studio01 .studio01-kicker {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wider);
  font-weight: var(--font-weight-medium);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.studio01-hero {
  padding-block: var(--space-10);
}
.studio01-hero h1 {
  font-size: var(--typography-hero-size);
  letter-spacing: var(--typography-heading-letterspacing);
  line-height: var(--typography-heading-lineheight);
  white-space: pre-line;
  margin-block: var(--space-5) var(--space-8);
}
.studio01 .studio01-introduction {
  gap: var(--studio01-column-gap);
}
.studio01-introduction > p {
  flex: 1 1 55%;
  max-width: var(--content-width-narrow);
  font-size: var(--typography-lead-size);
  line-height: var(--typography-lead-lineheight);
  color: var(--text-secondary);
}
.studio01-introduction > div {
  flex: 0 1 35%;
  min-width: 0;
}
.studio01-availability {
  display: block;
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  margin-block-end: var(--space-4);
  color: var(--text-muted);
}
.studio01-introduction .btn {
  white-space: normal;
}
.studio01-work {
  padding-block: var(--space-7) var(--studio01-section-gap);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.studio01 .studio01-section-heading {
  gap: var(--space-5);
  margin-block-end: var(--space-6);
}
.studio01-section-heading h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  margin-block-start: var(--space-3);
}
.studio01-section-heading > span {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.studio01 .studio01-projects {
  gap: var(--space-6);
}
.studio01-project {
  flex: 0 1 calc((100% - var(--space-6)) / 2);
  min-width: 0;
}
.studio01-project-media {
  overflow: hidden;
  border-radius: var(--media-radius);
}
.studio01-project-art {
  aspect-ratio: var(--media-aspect-video);
  min-height: calc(var(--space-4) * 14);
  padding: var(--space-6);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--space-5);
  background: var(--brand-primary);
  color: var(--text-on-brand);
